/**
 *
 * SelectClear is the clear button for the Select component.
 *
 * [Live Demo](https://www.primereact.org/select/)
 *
 * @module SelectClear
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { SelectRootInstance } from './SelectRoot.types';
/**
 * Defines passthrough(pt) options type in SelectClear component.
 */
export type SelectClearPassThroughType<E> = PassThroughType<SelectClearInstance, E>;
/**
 * Defines passthrough(pt) options of SelectClear component.
 */
export interface SelectClearPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SelectClearPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in SelectClear component.
 */
export interface SelectClearProps extends BaseComponentProps<SelectClearInstance, unknown, SelectClearPassThrough> {
}
/**
 * Defines valid state in SelectClear component.
 */
export interface SelectClearState {
}
/**
 * Defines the methods and properties exposed by SelectClear component.
 */
export interface SelectClearExposes {
    /**
     * The Select component instance.
     */
    select: SelectRootInstance | undefined | null;
}
/**
 * Instance of SelectClear component.
 */
export type SelectClearInstance = ComponentInstance<SelectClearProps, SelectClearState, SelectClearExposes>;
